const config = $("Config").first().json;
const rawItems = $input.all().map(i => i.json);
const firstItem = rawItems[0] || {};
const attachments = Array.isArray(firstItem.attachments) ? firstItem.attachments : rawItems;

function attachmentName(attachment) {
  return String(attachment.name || attachment.fileName || "").trim();
}

function isImage(attachment) {
  const name = attachmentName(attachment);
  const mime = String(attachment.mimeType || '').toLowerCase();
  return /\.(?:jpe?g|png|webp)$/i.test(name) && (!mime || mime.startsWith('image/'));
}

function timestamp(attachment) {
  const raw = attachment.date || attachment.dateLastActivity || attachment.createdAt || '';
  const parsed = raw ? Date.parse(raw) : NaN;
  if (Number.isFinite(parsed)) return parsed;
  const id = String(attachment.id || '');
  if (/^[0-9a-fA-F]{8}/.test(id)) return parseInt(id.slice(0, 8), 16) * 1000;
  return 0;
}

function aiMockupParts(attachment) {
  const match = attachmentName(attachment).match(/^mockup([\d_.]+)_(?:ai|ki)_(\d+)\.(?:jpe?g|png|webp)$/i);
  if (!match) return null;
  const sourceDigits = String(match[1]).replace(/[^\d]/g, '');
  const sourceNumber = sourceDigits ? Number.parseInt(sourceDigits, 10) : Number.POSITIVE_INFINITY;
  const variant = Number.parseInt(match[2], 10);
  return {
    sourceNumber: Number.isFinite(sourceNumber) ? sourceNumber : Number.POSITIVE_INFINITY,
    variant: Number.isFinite(variant) ? variant : Number.POSITIVE_INFINITY,
  };
}

const aiMockups = attachments
  .filter(isImage)
  .map((attachment) => ({ attachment, parts: aiMockupParts(attachment) }))
  .filter((entry) => entry.parts)
  .sort((a, b) =>
    a.parts.sourceNumber - b.parts.sourceNumber ||
    a.parts.variant - b.parts.variant ||
    timestamp(b.attachment) - timestamp(a.attachment) ||
    attachmentName(a.attachment).localeCompare(attachmentName(b.attachment), 'de')
  );

const selected = aiMockups[0] || null;
const mockup = selected ? selected.attachment : null;

if (!mockup) {
  return [{ json: {
    cardId: config.cardId,
    cardName: config.cardName,
    mockupOk: false,
    mockupError: "Kein KI-Mockup für Video gefunden. Videos dürfen nur aus generierten Mockups wie Mockup4376_ai_1.jpg oder Mockup4376_ki_1.jpg erstellt werden. Ausgangsmockups wie Mockup4376.jpg oder Mockup01.jpg werden nicht als Video-Input genutzt.",
    attachmentNames: attachments.map(attachmentName).filter(Boolean).join(", ")
  } }];
}

const previews = Array.isArray(mockup.previews) ? mockup.previews : [];
const bestPreview = previews
  .filter((preview) => preview && preview.url && preview.width && preview.height)
  .sort((a, b) => (b.width * b.height) - (a.width * a.height))[0];

const fn = mockup.fileName || mockup.name;
const originalUrl = "https://api.trello.com/1/cards/" + config.cardId + "/attachments/" + mockup.id + "/download/" + encodeURIComponent(fn);
const previewUrl = bestPreview && bestPreview.url ? bestPreview.url.replace("https://trello.com/1/", "https://api.trello.com/1/") : "";
const downloadUrl = previewUrl || originalUrl;

return [{ json: {
  cardId: config.cardId,
  cardName: config.cardName,
  mockupOk: true,
  selectedMockupName: attachmentName(mockup),
  selectedMockupAttachmentId: mockup.id,
  selectedMockupFileName: fn,
  selectedMockupMimeType: mockup.mimeType || "",
  selectedMockupKind: "ai_generated",
  selectedMockupSource: bestPreview ? "trello_preview_" + bestPreview.width + "x" + bestPreview.height : "original",
  downloadUrl
} }];

const config = $('Config').first().json;
const isAutomaticVideoRetry = Number(config.jobAttempts || 1) >= 2;
const staticData = $getWorkflowStaticData('global');
const now = new Date();
const dayKey = now.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
const hourKey = dayKey + 'T' + now.toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', hour12: false });
const MAX_GROK_PER_DAY = 80;
const MAX_GROK_PER_HOUR = 20;

if (staticData.grokDayKey !== dayKey) {
  staticData.grokDayKey = dayKey;
  staticData.grokDayCount = 0;
}

if (staticData.grokHourKey !== hourKey) {
  staticData.grokHourKey = hourKey;
  staticData.grokHourCount = 0;
}

if ((staticData.grokDayCount || 0) >= MAX_GROK_PER_DAY) {
  throw new Error('Grok safety cap reached: max ' + MAX_GROK_PER_DAY + ' video starts per day. Card: ' + config.cardId);
}

if ((staticData.grokHourCount || 0) >= MAX_GROK_PER_HOUR) {
  throw new Error('Grok safety cap reached: max ' + MAX_GROK_PER_HOUR + ' video starts per hour. Card: ' + config.cardId);
}

staticData.grokDayCount = (staticData.grokDayCount || 0) + 1;
staticData.grokHourCount = (staticData.grokHourCount || 0) + 1;
staticData.lastGrokStartAt = now.toISOString();
staticData.lastGrokCardId = config.cardId;

const binaryData = $input.first().binary;
if (!binaryData || !binaryData.data) throw new Error('Keine Binary-Daten');

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const mimeType = binaryData.data.mimeType || 'image/jpeg';
if (!mimeType.startsWith('image/')) {
  throw new Error('Download fehlgeschlagen: mimeType ist ' + mimeType + ' statt image/*. Trello-Auth Problem?');
}

const dataUri = 'data:' + mimeType + ';base64,' + base64;
const approxBytes = Buffer.byteLength(dataUri, 'utf8');
if (approxBytes > 5 * 1024 * 1024) {
  throw new Error('Grok Data-URI zu groß (' + approxBytes + ' Bytes). Bild vor Video verkleinern oder Upload-Flow verwenden.');
}

const standardPrompt = "Create a short cinematic product animation from the provided image, but treat the image as a locked reference frame for the sign. The sign artwork must stay EXACTLY the same from first frame to last frame: same text, same logo, same symbols, same proportions, same layout, same mounting, same wall position, same material, same color and same light color. CRITICAL COLOR LOCK: preserve the exact hue and color temperature from the source image for the entire video. A green sign must remain green. A red sign must remain red. Cool white must remain cool white. Warm white must remain warm white. Never fade, shift or morph any sign color toward white, yellow, blue or another color. Do not recolor the sign during zoom or dolly movement. Animate only very subtle light intensity, glow/reflection and a slow minimal camera dolly-in; the sign itself must not morph, warp, redraw, simplify, drift, resize, change font, change symbols or gain new elements. Do not add any extra objects, icons, letters, logos, decorative elements, people, stickers, faces, smiley faces, eyes, mouths, mascots, characters or anthropomorphic features. If the source image contains circles, dots, curves or logo shapes, keep them as flat sign design elements only. Keep the background stable and realistic; no new signs, no new wall graphics, no extra branding, no invented text. Use hyper-realistic commercial footage, natural wall texture, stable shadows, shallow depth of field. No audio.";
const hardenedRetryPrompt = "Create a short locked-off commercial product video from the provided image. This is a safety retry after a prior DESIGN_MORPH rejection. Treat the complete input image as a locked reference plate. Keep the camera fully static: no dolly, no zoom, no pan, no orbit, no crop change and no perspective change. The sign, logo and all letters must remain pixel-stable and identical in every frame: same text, font, symbols, outlines, proportions, spacing, position, mounting, material, hue, white temperature and light color. Do not redraw, interpolate, warp, bend, simplify, recolor, move, resize or replace any part of the sign. Animate only an extremely subtle, uniform light-intensity breathing of at most five percent and a natural reflection on the existing wall. Keep the background unchanged. Add no objects, people, text, branding, graphics or camera effects. If exact preservation is not possible, output a visually static shot rather than modifying the design. No audio.";
const prompt = isAutomaticVideoRetry ? hardenedRetryPrompt : standardPrompt;

return [{ json: {
  cardId: config.cardId,
  videoGenerationMode: isAutomaticVideoRetry ? 'locked_static_retry' : 'cinematic_standard',
  videoGenerationAttempt: Number(config.jobAttempts || 1),
  grokBody: {
    model: 'grok-imagine-video',
    prompt,
    image: { url: dataUri },
    duration: 4,
    resolution: '720p'
  }
} }];

const response = $input.first().json || {};
const config = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const providerError = response.error && typeof response.error === 'object' ? response.error : {};
const errorStatus = Number(
  providerError.status ||
  response.statusCode ||
  response.status ||
  0
);
const errorCode = String(providerError.code || response.code || '').toLowerCase();
const errorMessage = String(
  providerError.message ||
  response.message ||
  JSON.stringify(response).substring(0, 1000)
);
const serializedError = `${errorCode} ${errorMessage}`;
const rateLimited = errorStatus === 429;
const transientProviderFailure =
  [408, 425, 500, 502, 503, 504].includes(errorStatus) ||
  /econnrefused|econnreset|etimedout|err_network|socket hang up|upstream connect|connection refused|temporar(?:y|ily)|overloaded|service unavailable|try again later/i.test(serializedError);

if (rateLimited || transientProviderFailure) {
  const now = new Date();
  const cooldownMinutes = rateLimited ? 15 : 5;
  const cooldownUntil = new Date(Date.now() + cooldownMinutes * 60 * 1000);
  staticData.grokRateLimitedUntil = cooldownUntil.toISOString();
  staticData.lastGrokRateLimitAt = rateLimited ? now.toISOString() : staticData.lastGrokRateLimitAt;
  staticData.lastGrokProviderUnavailableAt = transientProviderFailure ? now.toISOString() : staticData.lastGrokProviderUnavailableAt;
  staticData.lastGrokRateLimitCardId = config.cardId;
  staticData.lastGrokProviderUnavailableCardId = config.cardId;

  return [{
    json: {
      rateLimited,
      transientVideoProviderFailure: transientProviderFailure,
      transient: true,
      reason: rateLimited
        ? 'Grok/xAI Provider Rate Limit 429'
        : `Grok/xAI Provider temporaer nicht verfuegbar: ${errorMessage}`,
      action: 'Automatischer Retry: Der Queue-Job wird freigegeben und spaeter erneut versucht. Die Karte bleibt in der Verarbeitungsliste; es wurde noch keine Kundenmail versendet.',
      cooldownUntil: cooldownUntil.toISOString(),
      cooldownUntilBerlin: cooldownUntil.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
      cardId: config.cardId,
      cardName: config.cardName,
      trelloCardUrl: config.cardUrl || (`https://trello.com/c/${config.cardId}`),
      errorStatus: errorStatus || null,
      errorCode: errorCode || (rateLimited ? 'rate_limited' : 'provider_unavailable'),
      errorMessage,
      workflowName: 'KI-Video Generator v1.0',
      observedAt: now.toISOString()
    }
  }];
}

if (response.error) {
  throw new Error(`Grok Submit fehlgeschlagen: ${JSON.stringify(response).substring(0, 500)}`);
}

const requestId = response.request_id || response.id || response.taskId;
if (!requestId) {
  throw new Error(`Keine Grok Request ID: ${JSON.stringify(response).substring(0, 500)}`);
}

staticData.grokRateLimitedUntil = null;
return [{
  json: {
    rateLimited: false,
    transientVideoProviderFailure: false,
    requestId,
    cardId: config.cardId,
    attempts: 0
  }
}];

const status = $input.first().json;
const prev = $('Save Request ID').first().json;
const attempts = (prev.attempts || 0) + 1;
const normalizedStatus = String(status.status || '').toLowerCase();

if (['done', 'completed', 'succeeded'].includes(normalizedStatus)) {
  const videoUrl = (status.video && (status.video.url || status.video.download_url)) ||
    status.video_url || status.url || status.download_url ||
    (status.output && (status.output.url || status.output.video_url || status.output.download_url)) ||
    (status.result && (status.result.url || status.result.video_url || status.result.download_url)) ||
    (Array.isArray(status.outputs) && status.outputs[0] && (status.outputs[0].url || status.outputs[0].video_url)) || '';

  if (!videoUrl) {
    throw new Error('Grok Task fertig, aber ohne Output-URL: ' + JSON.stringify(status).substring(0, 500));
  }

  return [{ json: {
    done: true,
    videoUrl,
    cardId: prev.cardId,
    attempts,
    rawResponse: JSON.stringify(status).substring(0, 2000)
  } }];
}

if (['failed', 'expired', 'canceled', 'cancelled'].includes(normalizedStatus)) {
  const serializedStatus = JSON.stringify(status).substring(0, 1000);
  const providerError = status.error && typeof status.error === 'object' ? status.error : {};
  const errorCode = String(providerError.code || status.code || '').toLowerCase();
  const errorMessage = String(providerError.message || status.message || serializedStatus);
  const transientProviderFailure = errorCode === 'service_unavailable' || /temporarily overloaded|try again later|service unavailable/i.test(errorMessage);

  if (transientProviderFailure) {
    const staticData = $getWorkflowStaticData('global');
    const now = new Date();
    const cooldownUntil = new Date(Date.now() + 20 * 60 * 1000);
    let config = {};
    try { config = $('Config').first().json || {}; } catch (error) { config = {}; }
    staticData.grokRateLimitedUntil = cooldownUntil.toISOString();
    staticData.lastGrokProviderUnavailableAt = now.toISOString();
    staticData.lastGrokProviderUnavailableCardId = prev.cardId;
    return [{ json: {
      done: false,
      transientVideoProviderFailure: true,
      rateLimited: true,
      transient: true,
      reason: 'Grok/xAI Provider temporaer nicht verfuegbar: ' + errorMessage,
      action: 'Automatischer Retry: Der Queue-Job wird freigegeben und spaeter mit einem neuen Video-Job erneut versucht. Die Karte wird nicht wegen temporaerer Provider-Ueberlastung nach Quote Ready zurueckgeschoben.',
      cooldownUntil: cooldownUntil.toISOString(),
      cooldownUntilBerlin: cooldownUntil.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
      cardId: prev.cardId,
      cardName: config.cardName || '',
      trelloCardUrl: config.cardUrl || ('https://trello.com/c/' + prev.cardId),
      requestId: prev.requestId,
      attempts,
      errorCode: errorCode || 'service_unavailable',
      errorMessage,
      workflowName: 'KI-Video Generator v1.0',
      observedAt: now.toISOString()
    } }];
  }

  throw new Error('Grok Video fehlgeschlagen: ' + serializedStatus.substring(0, 500));
}

if (attempts >= 60) throw new Error('Grok Timeout nach ' + attempts + ' Versuchen');

return [{ json: {
  done: false,
  requestId: prev.requestId,
  cardId: prev.cardId,
  attempts
} }];

const SOURCE_LIST_ID = '6a18389f5e45294188451924'; // Neue Angebote schicken + KI-Video
const VIDEO_SENT_LABEL_ID = '69ea8cb44dafe69b2a31350c'; // Video gesendet
const LEASE_MS = 2 * 60 * 60 * 1000; // Must exceed STOP/initial-delivery wait so one card cannot start multiple paid videos.

const claim = $input.first().json || {};
const job = claim.job || (claim.data && claim.data.job) || null;
if (!job || !job.id || !job.trello_card_id) {
  console.log('[KI VIDEO QUEUE] No job claimed. Reason: ' + (claim.reason || 'queue_empty') + '. Active leases: ' + String(claim.active_leases ?? 'unknown') + '/' + String(claim.max_active ?? 'unknown'));
  return [];
}

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const leaseUntil = new Date(now.getTime() + LEASE_MS);
staticData.kiVideoLeaseUntil = leaseUntil.toISOString();
staticData.kiVideoLeaseCardId = job.trello_card_id;
staticData.kiVideoLeaseCardName = job.card_name || '';
staticData.kiVideoLeaseAcquiredAt = now.toISOString();

const regenerateOnly = false;
const triggerLabel = { id: '', name: 'queue_trigger' };

return [{ json: {
  jobId: job.id,
  jobStatus: job.status,
  jobAttempts: job.attempts || 0,
  jobMaxAttempts: job.max_attempts || 3,
  queueSeq: job.queue_seq || null,
  queueEnteredAt: job.entered_at || null,
  queueLeaseUntil: job.lease_until || null,
  deliveryCycleKey: job.delivery_cycle_key || job.deliveryCycleKey || (job.metadata && job.metadata.delivery_cycle_key) || '',
  workerActiveLeasesBeforeClaim: claim.active_leases_before_claim ?? null,
  workerMaxActive: claim.max_active ?? 3,
  cardId: job.trello_card_id,
  cardName: job.card_name || '',
  cardUrl: job.trello_card_url || ('https://trello.com/c/' + job.trello_card_id),
  sourceListId: job.source_list_id || SOURCE_LIST_ID,
  videoSentLabelId: VIDEO_SENT_LABEL_ID,
  triggerLabelId: triggerLabel.id,
  triggerLabelName: triggerLabel.name,
  regenerateOnly,
  deliveryMode: regenerateOnly ? 'regenerate_only' : 'send_preview_email',
  videoProvider: 'grok',
  leaseAcquiredAt: now.toISOString(),
  leaseUntil: leaseUntil.toISOString()
} }];

const config = $('Config').first().json || {};
const rows = $input.all().map(i => i.json).filter(Boolean);
const row = Array.isArray(rows[0]) ? rows[0][0] : rows[0];

if (!row || !row.request_id || !row.customer_id) {
  return [{ json: {
    cardId: config.cardId,
    cardName: config.cardName,
    requestId: $('Extract Preview Request ID').first().json.requestId || '',
    requestUuid: '',
    customerId: '',
    acDealId: '',
    canonicalTrelloCardId: '',
    previewRequestOk: false,
    previewRequestError: 'No request/customer match in master_requests for Trello card ' + (config.cardId || '-')
  } }];
}

return [{ json: {
  cardId: config.cardId,
  cardName: config.cardName,
  requestId: row.request_id,
  requestUuid: row.id,
  customerId: row.customer_id,
  acDealId: row.ac_deal_id || '',
  canonicalTrelloCardId: row.trello_card_id || '',
  canonicalTrelloCardUrl: row.trello_card_url || '',
  finalValue: row.final_value || null,
  previewRequestOk: true,
  previewRequestError: ''
} }];

const rows = $input.all().map(i => i.json).filter(Boolean);
const customer = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const prev = $('Validate Preview Request').first().json;

const emailRaw = String(customer && customer.email || '').trim();
const email = emailRaw.toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const phone = String(customer && customer.phone || '').trim();

if (!emailValid && !phone) {
  throw new Error('Preview customer contact channel missing for request ' + prev.requestId + ': no valid email and no phone');
}

const roleAccount = false;

return [{ json: {
  ...prev,
  email: emailValid ? email : '',
  emailValid,
  emailMissing: !emailValid,
  skipCustomerEmail: !emailValid,
  whatsappFallbackOnly: !emailValid && !!phone,
  firstName: customer.first_name || '',
  lastName: customer.last_name || '',
  phone,
  country: customer.country || '',
  roleAccount
} }];

const prev = $('Validate Preview Customer').first().json;
const cardId = prev.cardId || $('Config').first().json.cardId || '';
const offerPlaceholder = 'https://angebote.neontrip.de/internal-offer-created-after-video';

return [{ json: {
  ...prev,
  pandaDocId: '',
  pandaDocStatus: 'replaced_by_neontrip_offer_api',
  shareLink: offerPlaceholder,
  previewQuoteOk: true,
  previewQuoteMissing: false,
  previewQuoteError: '',
  previewQuoteSource: 'neontrip_offers_api_after_video',
  previewQuoteEvidence: {
    source: 'neontrip_offers_api_after_video',
    card_id: cardId
  }
} }];

const config = $('Config').first().json;
const card = $input.first().json || {};
const customFieldItems = Array.isArray(card.customFieldItems) ? card.customFieldItems : [];
const NERDY_FORMS_FIELD_ID = '67a200bd23b1ffd304e63335';

const field = customFieldItems.find((item) => item.idCustomField === NERDY_FORMS_FIELD_ID);
const value = field && field.value ? field.value : {};
const customRequestId = String(value.text || value.number || value.date || '').trim();

const desc = String(card.desc || '');
const descMatch = desc.match(/(?:request[_ -]?id|nerdyforms?[_ -]?id|anfrage[_ -]?id)\s*[:#-]?\s*([a-zA-Z0-9_-]+)/i);
const descRequestId = descMatch ? String(descMatch[1]).trim() : '';
const requestId = customRequestId || descRequestId;

return [{ json: {
  ...config,
  requestId,
  requestIdSource: customRequestId ? 'trello_custom_field' : (descRequestId ? 'trello_description' : 'none')
} }];

