const base = $('Extract Preview Request ID').first().json;
const aliasResult = $input.first()?.json || {};
return [{
  json: {
    ...base,
    alias_fallback_attempted: true,
    alias_fallback_error: aliasResult.error?.message || aliasResult.message || null
  }
}];

const staticData = $getWorkflowStaticData('global');
const config = $('Config').first().json;
const input = $input.first().json || {};
let failure = {};
let preparedFailurePresent = false;
try {
  failure = $('Prepare Locked Offer Failure').first().json || {};
  preparedFailurePresent = Object.keys(failure).length > 0;
} catch (error) {
  failure = {};
}
const source = preparedFailurePresent ? failure : input;
const deliveryHandoff = input && typeof input.delivery === 'object' ? input.delivery : null;
const deliveryHandoffAccepted = Boolean(deliveryHandoff && ['ready', 'wait', 'paused', 'skip'].includes(String(deliveryHandoff.action || '')));
const currentLeaseCardId = staticData.kiVideoLeaseCardId || '';
const shouldRelease = !currentLeaseCardId || currentLeaseCardId === config.cardId;

if (shouldRelease) {
  staticData.kiVideoLeaseUntil = null;
  staticData.kiVideoLeaseCardId = null;
  staticData.kiVideoLeaseCardName = null;
  staticData.kiVideoLeaseAcquiredAt = null;
}

let sent = deliveryHandoffAccepted;
try {
  if (!sent) sent = $('Preview Delivery OK?').first().json.ok === true;
} catch (error) {
  sent = false;
}

let auditWriteOk = null;
let auditWriteError = null;
try {
  const auditResult = $('Audit: Company Brain Offer Failure').first().json || {};
  auditWriteOk = !auditResult.error;
  auditWriteError = auditResult.error ? JSON.stringify(auditResult.error).slice(0, 1000) : null;
} catch (error) {
  auditWriteOk = null;
}

const serialized = JSON.stringify(source).slice(0, 4000);
const retryable = source.retryable === true;
const rateLimited = source.rateLimited === true || /\b429\b|rate limit|too many requests/i.test(serialized);
const transientProviderFailure =
