const videos = attachments
  .filter(isGeneratedVideo)
  .sort((a, b) => timestamp(b) - timestamp(a));

const existingVideo = videos[0] || null;
const mockupTimestamp = selectedMockup ? timestamp(selectedMockup) : 0;
const videoTimestamp = existingVideo ? timestamp(existingVideo) : 0;
const reusableVideo = Boolean(
  mockup.mockupOk === true &&
  selectedMockup &&
  existingVideo &&
  videoTimestamp >= mockupTimestamp
);

const existingVideoFileName = existingVideo
  ? String(existingVideo.fileName || existingVideo.name || 'Mockup01_video.mp4')
  : '';

return [{ json: {
  ...mockup,
  reusableVideo,
  videoGenerationRequired: !reusableVideo,
  existingVideoAttachmentId: existingVideo ? existingVideo.id : null,
  existingVideoName: existingVideo ? attachmentName(existingVideo) : null,
  existingVideoDate: existingVideo && existingVideo.date ? existingVideo.date : null,
  existingVideoBytes: existingVideo ? Number(existingVideo.bytes || 0) : null,
  existingVideoDownloadUrl: existingVideo
    ? 'https://api.trello.com/1/cards/' + config.cardId + '/attachments/' + existingVideo.id + '/download/' + encodeURIComponent(existingVideoFileName)
    : null,
  selectedMockupDate: selectedMockup && selectedMockup.date ? selectedMockup.date : null,
  videoReuseReason: reusableVideo
    ? 'Vorhandenes KI-Video ist mindestens so neu wie das ausgewaehlte KI-Mockup und wird kostenfrei wiederverwendet.'
    : (existingVideo
      ? 'Vorhandenes Video ist aelter als das ausgewaehlte KI-Mockup; neue Generierung ist erforderlich.'
      : 'Kein wiederverwendbares KI-Video vorhanden; neue Generierung ist erforderlich.'),
  videoGenerationFingerprint: config.cardId + ':' + String(mockup.selectedMockupAttachmentId || 'missing')
} }];

const input = $input.first().json || {};
const candidates = [
  input?.content?.parts?.[0]?.text,
  input?.text,
  input?.output,
  input?.response,
].filter((value) => typeof value === 'string' && value.trim());

let parsed = null;
let parseError = '';
for (const candidate of candidates) {
  const cleaned = candidate.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '');
  try {
    parsed = JSON.parse(cleaned);
    break;
  } catch (error) {
    parseError = String(error?.message || error);
  }
}

const allowedIssues = new Set([
  'DESIGN_MORPH',
  'COLOR_SHIFT',
  'INVENTED_TEXT',
  'INVENTED_OBJECT',
  'UNWANTED_BRANDING',
  'SIGN_DISAPPEARS',
  'FLOATING_SIGN',
  'BAD_CROP',
  'OTHER',
]);
const confidence = Number(parsed?.confidence);
const issues = Array.isArray(parsed?.issues)
  ? [...new Set(parsed.issues.map((issue) => String(issue || '').trim().toUpperCase()).filter((issue) => allowedIssues.has(issue)))]
  : [];
const evidence = Array.isArray(parsed?.evidence)
  ? parsed.evidence.map((entry) => {
      const code = String(entry?.code || '').trim().toUpperCase();
      const timestamps = Array.isArray(entry?.timestamps)
        ? [...new Set(entry.timestamps.map(Number).filter((value) => Number.isFinite(value) && value >= 0 && value <= 30))].sort((a, b) => a - b).slice(0, 6)
        : [];
      return {
        code,
        timestamps,
        description: String(entry?.description || '').trim().slice(0, 300),
      };
    }).filter((entry) => allowedIssues.has(entry.code) && entry.description.length >= 12 && entry.timestamps.length > 0)
  : [];
const issueEvidence = evidence.filter((entry) => issues.includes(entry.code));
const structurallyValid =
  parsed &&
  typeof parsed.approved === 'boolean' &&
  Number.isFinite(confidence) &&
  confidence >= 0 &&
  confidence <= 1 &&
  Array.isArray(parsed.issues);

let jobAttempts = 1;
try {
  jobAttempts = Math.max(1, Number($('Config').first().json.jobAttempts || 1));
} catch (error) {
  jobAttempts = 1;
}

const normalApproval =
  structurallyValid &&
  parsed.approved === true &&
  confidence >= 0.7 &&
  issues.length === 0;
const evidenceBackedRejection =
  structurallyValid &&
  parsed.approved === false &&
  issues.length > 0 &&
  issueEvidence.length > 0;
const inconclusive = !normalApproval && !evidenceBackedRejection;
const fallbackWithoutVideo = !normalApproval && jobAttempts >= 3;
const fallbackReason = evidenceBackedRejection
  ? 'content_rejected_after_three_video_attempts'
  : 'inconclusive_after_three_qc_attempts';
const decision = normalApproval ? 'pass' : (evidenceBackedRejection ? 'reject' : 'inconclusive');
const videoContentQcOk = normalApproval;

const evidenceText = issueEvidence.length > 0
  ? issueEvidence.map((entry) => entry.code + '@' + entry.timestamps.join('/')).join(', ')
  : 'kein konkreter Zeitbeleg';
const issueText = issues.length > 0 ? issues.join(', ') : 'keine belegte Inhaltsabweichung';
const failureType = evidenceBackedRejection
  ? 'video_content_qc_failed'
  : (structurallyValid ? 'video_content_qc_inconclusive' : 'video_content_qc_unavailable');
const failureMessage = evidenceBackedRejection
  ? (fallbackWithoutVideo
    ? 'Auch der dritte KI-Video-Versuch hat eine konkrete Inhaltsabweichung (' + issueText + '; ' + evidenceText + '). Das fehlerhafte Video wird verworfen und das Angebot ohne Video versendet.'
    : 'KI-Video hat die Inhaltspruefung nicht bestanden (' + issueText + '; ' + evidenceText + '). Ein weiterer statischer Video-Versuch wird gestartet.')
  : (fallbackWithoutVideo
    ? 'KI-Video konnte auch im dritten Versuch nicht eindeutig freigegeben werden. Das Angebot wird ohne dieses Video versendet.'
    : 'KI-Video konnte nicht eindeutig geprueft werden. Ein weiterer statischer Video-Versuch wird gestartet.');

return [{ json: {
  videoContentQcOk,
  videoContentQcDecision: decision,
  videoContentQcInconclusive: inconclusive,
  videoContentQcFallbackWithoutVideo: fallbackWithoutVideo,
  videoContentQcFallbackReason: fallbackWithoutVideo ? fallbackReason : '',
  videoContentQcApproved: structurallyValid ? parsed.approved : false,
  videoContentQcConfidence: Number.isFinite(confidence) ? confidence : null,
  videoContentQcIssues: issues,
  videoContentQcEvidence: evidence,
  videoContentQcEvidenceBackedRejection: evidenceBackedRejection,
  videoContentQcRaw: candidates[0] ? String(candidates[0]).slice(0, 2000) : '',
  failureType: videoContentQcOk ? null : failureType,
  failureMessage: videoContentQcOk ? null : failureMessage,
  videoContentQcParseError: structurallyValid ? '' : parseError.slice(0, 300),
  checkedAt: new Date().toISOString(),
} }];

const reusable = $('Check Reusable Trello Video').first().json.reusableVideo === true;
const source = $('Strip Video Audio').first();
if (!source?.binary?.data) {
  throw new Error('Silent video binary missing after content QC');
}
return [{ json: { ...$json, reusableVideo: reusable }, binary: source.binary }];

